// Megaball Neo — a modern tribute to Ed & Al Mackey's Amiga classic.
// Game logic + bricks/ball/particles are Canvas2D; backdrop, title, paddle, capsules and banners
// are live Rive state machines (generated by rive-mcp, see tools/build-rive.mjs).
import { createMusic } from "./music.js";
import RiveFactory from "https://cdn.jsdelivr.net/npm/@rive-app/canvas-advanced@2.43.1/canvas_advanced.mjs";

const W = 1200, H = 800;
const FIELD = { left: 276, right: 924, top: 64, bottom: H };
const COLS = 12, BW = 54, BH = 24, BRICK_TOP = 112;
const PADDLE_Y = 742, BALL_R = 8;
const MAX_BALL_SPEED = 680; // px/s hard cap, whatever the round, return count or FAST capsule
const PADDLE_CX = 160, PADDLE_CY = 52; // paddle artboard pivot
const SIZE = { shrink: 4, normal: 20, expand: 50 };
const paddleWidth = (size) => 60 + 2.2 * size + 24; // bar inner + end caps (matches paddle.riv poses)

// ------------------------------------------------------------------ assets
const $ = (id) => document.getElementById(id);
const stage = $("stage"), bgCanvas = $("bg"), gameCanvas = $("game"), fxCanvas = $("fx");
const ctx = gameCanvas.getContext("2d");

const [rive, tokens, files] = await Promise.all([
  RiveFactory({ locateFile: () => "https://cdn.jsdelivr.net/npm/@rive-app/canvas-advanced@2.43.1/rive.wasm" }),
  fetch("rive/tokens.json").then((r) => r.json()),
  Promise.all(["backdrop", "title", "paddle", "capsules", "banner"].map((n) => fetch(`rive/${n}.riv`).then((r) => r.arrayBuffer()))),
  document.fonts.load('32px "Audiowide"'), document.fonts.load('16px "InterMB"'),
]);
const P = tokens.palette, RAINBOW = tokens.rainbow, WARM = tokens.warm;
const [fBackdrop, fTitle, fPaddle, fCaps, fBanner] = await Promise.all(files.map((b) => rive.load(new Uint8Array(b))));
const bgRenderer = rive.makeRenderer(bgCanvas);
const fxRenderer = rive.makeRenderer(fxCanvas);
$("loading").classList.add("hidden");

class RiveActor {
  constructor(file, artboard, sm) {
    this.ab = file.artboardByName(artboard);
    this.sm = new rive.StateMachineInstance(this.ab.stateMachineByName(sm), this.ab);
    this.inputs = {};
    for (let i = 0; i < this.sm.inputCount(); i++) { const inp = this.sm.input(i); this.inputs[inp.name] = inp; }
    const b = this.ab.bounds;
    this.w = b.maxX - b.minX; this.h = b.maxY - b.minY;
  }
  num(name, v) { this.inputs[name].asNumber().value = v; }
  bool(name, v) { const i = this.inputs[name].asBool(); if (i.value !== v) i.value = v; }
  fire(name) { this.inputs[name].asTrigger().fire(); }
  text(run, value) { this.ab.textRun(run).text = value; }
  advance(dt) { this.sm.advanceAndApply(dt); }
  // draw with the artboard's top-left at stage (x, y), scaled by k
  draw(renderer, x, y, k = 1) {
    const s = scale;
    renderer.save();
    renderer.align(rive.Fit.fill, rive.Alignment.center,
      { minX: x * s, minY: y * s, maxX: (x + this.w * k) * s, maxY: (y + this.h * k) * s }, this.ab.bounds);
    this.ab.draw(renderer);
    renderer.restore();
  }
  dispose() { this.sm.delete(); this.ab.delete(); }
}

const backdrop = new RiveActor(fBackdrop, "Backdrop", "BackdropSM");
const paddleActor = new RiveActor(fPaddle, "Paddle", "PaddleSM");
const banner = new RiveActor(fBanner, "Banner", "BannerSM");
let title = null;

const KINDS = {
  E: { name: "EXPAND", good: true }, S: { name: "SLOW", good: true }, C: { name: "CATCH", good: true },
  L: { name: "LASER", good: true }, M: { name: "MULTIBALL", good: true }, B: { name: "MEGA BALL", good: true },
  P: { name: "EXTRA LIFE", good: true }, X: { name: "SHRINK", good: false }, F: { name: "FAST", good: false },
};
const legend = Object.keys(KINDS).map((k) => ({ k, actor: new RiveActor(fCaps, `Cap${k}`, "CapSM") }));

// ------------------------------------------------------------------ canvas sizing
let scale = 1;
function resize() {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const cssW = stage.clientWidth;
  for (const c of [bgCanvas, gameCanvas, fxCanvas]) { c.width = Math.round(cssW * dpr); c.height = Math.round((cssW * dpr * H) / W); }
  scale = gameCanvas.width / W;
  brickSprites.clear();
}
window.addEventListener("resize", resize);

// ------------------------------------------------------------------ audio (synthesised)
const Sound = (() => {
  let ac = null, master = null, muted = false, music = null, wanted = null;
  const init = () => {
    if (ac) return;
    ac = new (window.AudioContext || window.webkitAudioContext)();
    master = ac.createGain(); master.gain.value = 0.28; master.connect(ac.destination);
    const musicOut = ac.createGain(); musicOut.gain.value = 0.6; musicOut.connect(ac.destination);
    music = createMusic(ac, musicOut);
    if (wanted) music.play(wanted);
  };
  const tone = (freq, dur, type = "square", vol = 0.5, slide = 0, delay = 0) => {
    if (!ac || muted) return;
    const t = ac.currentTime + delay, o = ac.createOscillator(), g = ac.createGain();
    o.type = type; o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t + dur);
    g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    o.connect(g); g.connect(master); o.start(t); o.stop(t + dur + 0.02);
  };
  const noise = (dur, vol = 0.4, delay = 0) => {
    if (!ac || muted) return;
    const t = ac.currentTime + delay, len = Math.floor(ac.sampleRate * dur), buf = ac.createBuffer(1, len, ac.sampleRate), d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const src = ac.createBufferSource(), g = ac.createGain(), f = ac.createBiquadFilter();
    f.type = "lowpass"; f.frequency.value = 1800; src.buffer = buf; g.gain.value = vol;
    src.connect(f); f.connect(g); g.connect(master); src.start(t);
  };
  const PENTA = [0, 2, 4, 7, 9, 12, 14, 16, 19];
  return {
    get ready() { return !!ac; }, init, get muted() { return muted; }, toggle() { muted = !muted; music?.mute(muted); return muted; },
    // background music: "title" | "game" | null (fade out)
    music: (name) => { wanted = name; if (!music) return; if (name) music.play(name); else music.stop(); },
    pauseMusic: (p) => music?.pause(p),
    paddle: () => { tone(220, 0.09, "square", 0.35, 110); tone(440, 0.06, "triangle", 0.2); },
    wall: () => tone(330, 0.04, "triangle", 0.2),
    brick: (row) => tone(440 * Math.pow(2, PENTA[row % PENTA.length] / 12), 0.12, "triangle", 0.45),
    metal: () => { tone(1320, 0.12, "square", 0.18); tone(1980, 0.18, "sine", 0.15); },
    gold: () => tone(1760, 0.08, "sine", 0.18),
    boom: () => { noise(0.45, 0.6); tone(90, 0.4, "sawtooth", 0.35, -60); },
    laser: () => tone(1400, 0.12, "sawtooth", 0.14, -1100),
    power: (good) => (good ? [0, 4, 7, 12] : [7, 3, 0, -5]).forEach((n, i) => tone(523 * Math.pow(2, n / 12), 0.14, "square", 0.25, 0, i * 0.06)),
    lose: () => [0, -3, -7, -12].forEach((n, i) => tone(392 * Math.pow(2, n / 12), 0.22, "sawtooth", 0.25, -40, i * 0.14)),
    clear: () => [0, 4, 7, 12, 7, 12, 16, 19].forEach((n, i) => tone(523 * Math.pow(2, n / 12), 0.16, "square", 0.22, 0, i * 0.08)),
    launch: () => tone(660, 0.1, "square", 0.25, 440),
  };
})();

// ------------------------------------------------------------------ levels
// . empty  1-8 rainbow  s silver (multi-hit)  g gold (indestructible)  x explosive  ? mystery (always drops)
const LEVELS = [
  { name: "RAINBOW ROAD", map: ["............", "111111111111", "222222222222", "333333333333", "444444444444", "555555555555", "666666666666", "777777777777"] },
  { name: "THE PYRAMID", map: [".....88.....", "....7777....", "...666666...", "..55555555..", ".4444?44444.", "333333333333", "2222x22x2222", "ssss....ssss"] },
  { name: "SPACE INVADERS", map: ["..5......5..", "...5....5...", "..55555555..", ".55.5555.55.", "5555?55?5555", "5.55555555.5", "5.5......5.5", "...55..55...", "............", "gg..gggg..gg"] },
  { name: "THE FORTRESS", map: ["gggggggggggg", "g..........g", "g.33333333.g", "g.3?4444?3.g", "g.34x55x43.g", "g.3?4444?3.g", "g.33333333.g", "g..........g", "gggg....gggg"] },
  { name: "TWIN DIAMONDS", map: ["..2......6..", ".212....656.", "21x12..65x56", ".212....656.", "..2......6..", ".....ss.....", "....s??s....", ".....ss....."] },
  { name: "COPPER BARS", map: ["ssssssssssss", "888888888888", "............", "777777777777", "ssssssssssss", "666666666666", "............", "555555555555", "xx..xxxx..xx"] },
  { name: "CHECKMATE", map: ["1.2.3.4.5.6.", ".2.3.4.5.6.7", "3.4.5.?.7.8.", ".4.5.6.7.8.1", "5.6.7.8.1.2.", ".6.?.8.1.2.3", "g..g..g..g.."] },
  { name: "MEGA CORE", map: ["?ssssssssss?", "s8888888888s", "s8777777778s", "s87?6666?78s", "s8766xx6678s", "s87?6666?78s", "s8777777778s", "s8888888888s", "............", "....gggg...."] },
];

// ------------------------------------------------------------------ helpers
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const rand = (a, b) => a + Math.random() * (b - a);
const fmt = (n) => n.toLocaleString("en-US");
function rrect(c, x, y, w, h, r) { c.beginPath(); c.roundRect(x, y, w, h, r); }
let hiScore = 0;
try { hiScore = Number(localStorage.getItem("megaball-neo-hi")) || 0; } catch {}

// ------------------------------------------------------------------ brick sprites (cached per scale)
const brickSprites = new Map();
function brickSprite(key, draw) {
  let c = brickSprites.get(key);
  if (!c) {
    c = document.createElement("canvas");
    c.width = Math.ceil((BW + 8) * scale); c.height = Math.ceil((BH + 8) * scale);
    const g = c.getContext("2d"); g.scale(scale, scale); g.translate(4, 4); draw(g);
    brickSprites.set(key, c);
  }
  return c;
}
function paintBrick(g, top, bottom, rim, highlight = 0.45) {
  const w = BW - 4, h = BH - 4;
  const grad = g.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, top); grad.addColorStop(1, bottom);
  g.fillStyle = grad; rrect(g, 2, 2, w, h, 5); g.fill();
  g.globalAlpha = highlight; g.fillStyle = P.text; rrect(g, 7, 4.5, w - 10, 3, 1.5); g.fill();
  g.globalAlpha = 0.35; g.fillStyle = "#000"; rrect(g, 5, h - 2, w - 6, 2, 1); g.fill();
  g.globalAlpha = 1; g.strokeStyle = rim; g.lineWidth = 1; rrect(g, 2.5, 2.5, w - 1, h - 1, 4.5); g.stroke();
}
function spriteFor(b) {
  switch (b.type) {
    case "n": return brickSprite(`n${b.color}`, (g) => { const c = RAINBOW[b.color]; paintBrick(g, c.light, c.dark, c.base + "aa"); });
    case "s": return brickSprite(`s${b.hp}`, (g) => { paintBrick(g, b.hp > 1 ? "#f2f1f7" : "#c9c7d6", b.hp > 1 ? "#7d7a92" : "#5d5a70", "#ffffffaa", 0.8);
      if (b.hp === 1) { g.strokeStyle = "#0008"; g.lineWidth = 1.2; g.beginPath(); g.moveTo(14, 4); g.lineTo(20, 12); g.lineTo(16, 20); g.moveTo(34, 5); g.lineTo(30, 13); g.stroke(); } });
    case "g": return brickSprite("g", (g) => { paintBrick(g, "#ffe08a", WARM.primary[0], "#fff3", 0.7);
      g.strokeStyle = "#7a3d00aa"; g.lineWidth = 1.5; rrect(g, 7, 6, BW - 14, BH - 12, 3); g.stroke(); });
    case "x": return brickSprite("x", (g) => { paintBrick(g, "#3a1420", "#1c0a10", WARM.accent[1], 0.2);
      g.fillStyle = WARM.accent[1]; g.font = '700 13px "Audiowide"'; g.textAlign = "center"; g.textBaseline = "middle"; g.fillText("✸", BW / 2 - 2, BH / 2 - 1); });
    case "?": return brickSprite("?", (g) => { paintBrick(g, tokens.gradients.primary[0], tokens.gradients.primary[1], "#fff6", 0.5);
      g.fillStyle = P.text; g.font = '15px "Audiowide"'; g.textAlign = "center"; g.textBaseline = "middle"; g.fillText("?", BW / 2 - 2, BH / 2 - 1); });
  }
}

// ------------------------------------------------------------------ game state
const S = {
  mode: "title", // title | ready | play | clear | over
  score: 0, lives: 3, round: 0, nextLifeAt: 20000,
  bricks: [], balls: [], caps: [], bolts: [], parts: [], popups: [],
  paddle: { x: W / 2, size: SIZE.normal, target: SIZE.normal, vx: 0 },
  fx: { laser: 0, catch: 0, slow: 0, fast: 0, mega: 0 },
  shake: 0, flash: 0, time: 0, modeT: 0, laserCd: 0, hits: 0, returns: 0, paused: false,
};
const keys = new Set();
let pointerX = null;

function loadRound(n) {
  const L = LEVELS[n % LEVELS.length];
  S.bricks = [];
  L.map.forEach((row, r) => [...row].forEach((ch, c) => {
    if (ch === ".") return;
    const b = { r, c, x: FIELD.left + c * BW, y: BRICK_TOP + r * BH, alive: true, hit: 0 };
    if (ch >= "1" && ch <= "8") Object.assign(b, { type: "n", color: +ch - 1, hp: 1, pts: 40 + +ch * 10 });
    else if (ch === "s") Object.assign(b, { type: "s", hp: 2 + Math.floor(n / 8), pts: 50 * (1 + Math.floor(n / 4)) });
    else if (ch === "g") Object.assign(b, { type: "g", hp: Infinity, pts: 0 });
    else if (ch === "x") Object.assign(b, { type: "x", hp: 1, pts: 100 });
    else if (ch === "?") Object.assign(b, { type: "?", hp: 1, pts: 150 });
    S.bricks.push(b);
  }));
  S.grid = new Map(S.bricks.map((b) => [`${b.r},${b.c}`, b]));
}

function baseSpeed() {
  // like the original, every return off the paddle speeds the ball up (reset when a ball is lost)
  let s = 400 + Math.min(S.round, 10) * 18 + S.returns * 10;
  if (S.fx.slow > 0) s *= 0.72;
  if (S.fx.fast > 0) s *= 1.25;
  return Math.min(s, MAX_BALL_SPEED);
}

function resetPaddleFx() {
  S.fx = { laser: 0, catch: 0, slow: 0, fast: 0, mega: 0 };
  S.paddle.target = SIZE.normal;
  for (const c of S.caps) c.actor.dispose();
  S.caps = []; S.bolts = [];
}

function serve() {
  S.balls = [{ x: S.paddle.x, y: PADDLE_Y - 12 - BALL_R, vx: 0, vy: 0, stuck: true, offset: 0, trail: [] }];
  S.hits = 0; S.returns = 0;
}

function startRound(first = false) {
  if (!first) S.round++;
  loadRound(S.round);
  resetPaddleFx();
  serve();
  setMode("ready");
  showBanner(`ROUND ${S.round + 1}`, LEVELS[S.round % LEVELS.length].name + (S.round >= LEVELS.length ? `  ·  LOOP ${Math.floor(S.round / LEVELS.length) + 1}` : ""), "flash");
}

function newGame() {
  Object.assign(S, { score: 0, lives: 3, round: 0, nextLifeAt: 20000 });
  S.paddle.x = W / 2; S.paddle.size = SIZE.normal;
  if (title) { title.dispose(); title = null; }
  Sound.music("game");
  startRound(true);
}

function setMode(m) { S.mode = m; S.modeT = 0; stage.classList.toggle("show-cursor", m === "title" || m === "over"); }

function showBanner(head, sub, how) {
  banner.text("headline", head);
  banner.text("sub", sub);
  banner.fire(how);
}

function toTitle() {
  if (S.mode === "over") banner.fire("exit");
  S.bricks = []; S.balls = []; resetPaddleFx();
  title = new RiveActor(fTitle, "Title", "TitleSM");
  setMode("title");
  Sound.music("title");
}

// ------------------------------------------------------------------ input
function action() {
  Sound.init();
  if (S.paused) return;
  if (S.mode === "title") return newGame();
  if (S.mode === "over") { if (S.modeT > 1.2) toTitle(); return; }
  let launched = false;
  for (const b of S.balls) if (b.stuck) { launch(b); launched = true; }
  if (!launched && S.fx.laser > 0) fireLaser();
}
function launch(b) {
  const sp = baseSpeed(), ang = clamp(b.offset / (paddleWidth(S.paddle.size) / 2), -1, 1) * 0.9 + (b.offset === 0 ? rand(-0.25, 0.25) : 0);
  b.stuck = false; b.vx = Math.sin(ang) * sp; b.vy = -Math.cos(ang) * sp;
  if (S.mode === "ready") setMode("play");
  Sound.launch();
}
function fireLaser() {
  if (S.laserCd > 0) return;
  S.laserCd = 0.22;
  const half = (60 + 2.2 * S.paddle.size) / 2;
  S.bolts.push({ x: S.paddle.x - half, y: PADDLE_Y - 26 }, { x: S.paddle.x + half, y: PADDLE_Y - 26 });
  Sound.laser();
}
function togglePause() {
  if (S.mode !== "play" && S.mode !== "ready") return;
  S.paused = !S.paused;
  if (S.paused) showBanner("PAUSED", "PRESS P TO RESUME", "enter"); else banner.fire("exit");
  Sound.pauseMusic(S.paused);
}

window.addEventListener("keydown", (e) => {
  if (["ArrowLeft", "ArrowRight", " ", "Space"].includes(e.key)) e.preventDefault();
  if (e.repeat) return;
  keys.add(e.key);
  if (e.key === " " || e.key === "Enter") action();
  else if (e.key === "p" || e.key === "P" || e.key === "Escape") togglePause();
  else if (e.key === "m" || e.key === "M") {
    // audio can only start after a gesture: on the title the first M press starts the theme instead of muting
    if (!Sound.ready) { Sound.init(); return; }
    Sound.toggle();
  }
});
window.addEventListener("keyup", (e) => keys.delete(e.key));
const toStageX = (e) => ((e.clientX - stage.getBoundingClientRect().left) / stage.clientWidth) * W;
stage.addEventListener("pointermove", (e) => { pointerX = toStageX(e); });
stage.addEventListener("pointerdown", (e) => { pointerX = toStageX(e); action(); });
window.addEventListener("blur", () => { if (!S.paused && (S.mode === "play")) togglePause(); });

// ------------------------------------------------------------------ effects
function burst(x, y, color, n = 14, speed = 260) {
  for (let i = 0; i < n && S.parts.length < 700; i++) {
    const a = rand(0, Math.PI * 2), v = rand(speed * 0.3, speed);
    S.parts.push({ x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v - 80, life: rand(0.4, 0.9), max: 0.9, size: rand(2, 5), color, rot: rand(0, 6), vr: rand(-10, 10) });
  }
}
function popup(x, y, text, color = P.text) { S.popups.push({ x, y, text, color, t: 0 }); }
function addScore(n) {
  S.score += n;
  if (S.score >= S.nextLifeAt) { S.lives++; S.nextLifeAt += 20000; popup(S.paddle.x, PADDLE_Y - 40, "1UP!", P.accent); Sound.power(true); }
}

function brickColor(b) {
  return b.type === "n" ? RAINBOW[b.color].base : b.type === "s" ? "#d9d7e6" : b.type === "g" ? "#ffd36b" : b.type === "x" ? WARM.accent[1] : P.primary;
}

function damage(b, byMega = false) {
  if (!b.alive) return;
  if (b.type === "g") { b.hit = 1; Sound.gold(); return; }
  b.hp -= byMega ? b.hp : 1;
  b.hit = 1;
  if (b.hp > 0) { Sound.metal(); burst(b.x + BW / 2, b.y + BH / 2, "#ffffff", 5, 160); return; }
  b.alive = false;
  S.grid.delete(`${b.r},${b.c}`);
  addScore(b.pts);
  const cx = b.x + BW / 2, cy = b.y + BH / 2;
  burst(cx, cy, brickColor(b), b.type === "x" ? 26 : 14);
  if (b.type === "s") Sound.metal(); else Sound.brick(b.r);
  if (b.type === "?" || (b.type !== "x" && Math.random() < 0.11)) dropCapsule(cx, cy, b.type === "?");
  if (b.type === "x") explode(b);
}

function explode(b) {
  S.shake = Math.max(S.shake, 10); S.flash = 0.35;
  Sound.boom();
  S.parts.push({ ring: true, x: b.x + BW / 2, y: b.y + BH / 2, life: 0.45, max: 0.45 });
  setTimeout(() => {
    for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) {
      const n = S.grid.get(`${b.r + dr},${b.c + dc}`);
      if (n && n.type !== "g") damage(n, true);
    }
  }, 70);
}

function dropCapsule(x, y, rare) {
  if (S.caps.length >= 3 || S.balls.length > 6) return;
  const pool = rare ? "EEMMLLBBCP" : "EEESSCCLLMMBXXFFP";
  let k = pool[Math.floor(Math.random() * pool.length)];
  if (k === "P" && Math.random() < 0.5) k = "E";
  S.caps.push({ k, x, y, vy: 140, actor: new RiveActor(fCaps, `Cap${k}`, "CapSM") });
}

function applyCapsule(k) {
  const good = KINDS[k].good;
  Sound.power(good);
  addScore(good ? 100 : 250);
  popup(S.paddle.x, PADDLE_Y - 44, KINDS[k].name, good ? P.accent : WARM.accent[0]);
  paddleActor.fire("hit");
  switch (k) {
    case "E": S.paddle.target = SIZE.expand; break;
    case "X": S.paddle.target = SIZE.shrink; break;
    case "S": S.fx.slow = 12; S.fx.fast = 0; retime(); break;
    case "F": S.fx.fast = 10; S.fx.slow = 0; retime(); break;
    case "C": S.fx.catch = 15; break;
    case "L": S.fx.laser = 12; break;
    case "B": S.fx.mega = 10; break;
    case "P": S.lives++; popup(S.paddle.x, PADDLE_Y - 70, "1UP!", P.accent); break;
    case "M": {
      const extra = [];
      for (const b of S.balls.slice(0, 4)) {
        if (b.stuck) launch(b);
        const sp = Math.hypot(b.vx, b.vy), a = Math.atan2(b.vy, b.vx);
        for (const d of [-0.45, 0.45]) extra.push({ x: b.x, y: b.y, vx: Math.cos(a + d) * sp, vy: Math.sin(a + d) * sp, stuck: false, offset: 0, trail: [] });
      }
      S.balls.push(...extra);
      break;
    }
  }
}
function retime() { for (const b of S.balls) if (!b.stuck) normalise(b); }
function normalise(b) {
  const sp = baseSpeed(), m = Math.hypot(b.vx, b.vy) || 1;
  b.vx = (b.vx / m) * sp; b.vy = (b.vy / m) * sp;
  // never let the ball get stuck in near-horizontal loops
  if (Math.abs(b.vy) < sp * 0.28) { b.vy = Math.sign(b.vy || -1) * sp * 0.28; b.vx = Math.sign(b.vx || 1) * Math.sqrt(sp * sp - b.vy * b.vy); }
}

// ------------------------------------------------------------------ simulation
function update(dt) {
  S.time += dt; S.modeT += dt;
  S.shake = Math.max(0, S.shake - dt * 40); S.flash = Math.max(0, S.flash - dt);
  for (const k of Object.keys(S.fx)) if (S.fx[k] > 0) { S.fx[k] = Math.max(0, S.fx[k] - dt); if (S.fx[k] === 0 && (k === "slow" || k === "fast")) retime(); }
  S.laserCd = Math.max(0, S.laserCd - dt);

  // paddle
  const pd = S.paddle, prevX = pd.x;
  pd.size += (pd.target - pd.size) * Math.min(1, dt * 10);
  const half = paddleWidth(pd.size) / 2;
  if (keys.has("ArrowLeft") || keys.has("a")) { pd.x -= 900 * dt; pointerX = null; }
  if (keys.has("ArrowRight") || keys.has("d")) { pd.x += 900 * dt; pointerX = null; }
  if (pointerX !== null) pd.x += (pointerX - pd.x) * Math.min(1, dt * 30);
  pd.x = clamp(pd.x, FIELD.left + half, FIELD.right - half);
  pd.vx = (pd.x - prevX) / Math.max(dt, 1e-4);
  paddleActor.num("size", pd.size);
  paddleActor.bool("laser", S.fx.laser > 0);
  paddleActor.bool("magnet", S.fx.catch > 0);

  if (S.mode === "ready" && S.modeT > 3) for (const b of S.balls) if (b.stuck) launch(b);

  // balls
  for (const b of S.balls) {
    if (b.stuck) { b.x = pd.x + b.offset; b.y = PADDLE_Y - 12 - BALL_R; b.trail.length = 0; continue; }
    b.trail.push({ x: b.x, y: b.y }); if (b.trail.length > 12) b.trail.shift();
    const dist = Math.hypot(b.vx, b.vy) * dt, steps = Math.max(1, Math.ceil(dist / 4));
    for (let i = 0; i < steps && !b.dead && !b.stuck; i++) stepBall(b, dt / steps, half);
  }
  const before = S.balls.length;
  S.balls = S.balls.filter((b) => !b.dead);
  if (before && !S.balls.length && (S.mode === "play" || S.mode === "ready")) loseLife();

  // capsules
  for (const c of S.caps) {
    c.y += c.vy * dt; c.actor.advance(dt);
    if (c.y + 12 >= PADDLE_Y - 12 && c.y - 12 <= PADDLE_Y + 12 && Math.abs(c.x - pd.x) <= half + 30) { c.got = true; applyCapsule(c.k); }
    if (c.got || c.y > H + 30) { c.dead = true; c.actor.dispose(); }
  }
  S.caps = S.caps.filter((c) => !c.dead);

  // lasers
  for (const l of S.bolts) {
    l.y -= 950 * dt;
    if (l.y < FIELD.top) l.dead = true;
    const c = Math.floor((l.x - FIELD.left) / BW), r = Math.floor((l.y - BRICK_TOP) / BH);
    const br = S.grid.get(`${r},${c}`);
    if (br && br.alive) { damage(br); burst(l.x, l.y, WARM.primary[0], 4, 120); l.dead = true; }
  }
  S.bolts = S.bolts.filter((l) => !l.dead);

  // particles + popups
  for (const p of S.parts) {
    p.life -= dt;
    if (!p.ring) { p.vy += 900 * dt; p.x += p.vx * dt; p.y += p.vy * dt; p.rot += p.vr * dt; }
  }
  S.parts = S.parts.filter((p) => p.life > 0);
  for (const p of S.popups) p.t += dt;
  S.popups = S.popups.filter((p) => p.t < 1.1);
  for (const b of S.bricks) if (b.hit > 0) b.hit = Math.max(0, b.hit - dt * 5);

  if (S.mode === "play" && !S.bricks.some((b) => b.alive && b.type !== "g")) roundClear();
  if (S.mode === "clear" && S.modeT > 2.6) startRound();
}

function stepBall(b, dt, half) {
  const ox = b.x, oy = b.y;
  b.x += b.vx * dt; b.y += b.vy * dt;
  // walls
  if (b.x - BALL_R < FIELD.left) { b.x = FIELD.left + BALL_R; b.vx = Math.abs(b.vx); Sound.wall(); }
  if (b.x + BALL_R > FIELD.right) { b.x = FIELD.right - BALL_R; b.vx = -Math.abs(b.vx); Sound.wall(); }
  if (b.y - BALL_R < FIELD.top) { b.y = FIELD.top + BALL_R; b.vy = Math.abs(b.vy); Sound.wall(); }
  if (b.y - BALL_R > H) { b.dead = true; return; }

  // paddle (only when travelling down and arriving from above)
  const top = PADDLE_Y - 12, pd = S.paddle;
  if (b.vy > 0 && b.y + BALL_R >= top && oy + BALL_R <= top + 8 && Math.abs(b.x - pd.x) <= half + BALL_R) {
    b.y = top - BALL_R;
    S.returns++;
    const off = clamp((b.x - pd.x) / half, -1, 1), sp = baseSpeed();
    const ang = off * 1.05 + clamp(pd.vx / 4000, -0.15, 0.15);
    b.vx = Math.sin(ang) * sp; b.vy = -Math.abs(Math.cos(ang) * sp);
    normalise(b);
    paddleActor.fire("hit");
    Sound.paddle();
    if (S.fx.catch > 0) { b.stuck = true; b.offset = b.x - pd.x; }
    return;
  }

  // bricks: test the cells the ball overlaps
  const c0 = Math.floor((b.x - BALL_R - FIELD.left) / BW), c1 = Math.floor((b.x + BALL_R - FIELD.left) / BW);
  const r0 = Math.floor((b.y - BALL_R - BRICK_TOP) / BH), r1 = Math.floor((b.y + BALL_R - BRICK_TOP) / BH);
  for (let r = r0; r <= r1; r++) for (let c = c0; c <= c1; c++) {
    const br = S.grid.get(`${r},${c}`);
    if (!br || !br.alive) continue;
    const nx = clamp(b.x, br.x, br.x + BW), ny = clamp(b.y, br.y, br.y + BH);
    const dx = b.x - nx, dy = b.y - ny;
    if (dx * dx + dy * dy > BALL_R * BALL_R) continue;
    S.hits++;
    const mega = S.fx.mega > 0 && br.type !== "g";
    damage(br, mega);
    if (mega) continue;
    // resolve against the side we came from
    const fromX = ox < br.x ? -1 : ox > br.x + BW ? 1 : 0, fromY = oy < br.y ? -1 : oy > br.y + BH ? 1 : 0;
    if (fromY && (!fromX || Math.abs(dy) >= Math.abs(dx))) { b.vy = fromY * Math.abs(b.vy); b.y = fromY < 0 ? br.y - BALL_R : br.y + BH + BALL_R; }
    else if (fromX) { b.vx = fromX * Math.abs(b.vx); b.x = fromX < 0 ? br.x - BALL_R : br.x + BW + BALL_R; }
    else { b.vy = -b.vy; b.x = ox; b.y = oy; }
    if (br.type === "g") { const a = rand(-0.08, 0.08), cs = Math.cos(a), sn = Math.sin(a); [b.vx, b.vy] = [b.vx * cs - b.vy * sn, b.vx * sn + b.vy * cs]; }
    normalise(b);
    return;
  }
}

function loseLife() {
  S.lives--;
  Sound.lose();
  S.shake = 14;
  burst(S.paddle.x, PADDLE_Y, P.primary, 40, 380);
  resetPaddleFx();
  if (S.lives < 0) {
    S.lives = 0;
    if (S.score > hiScore) { hiScore = S.score; try { localStorage.setItem("megaball-neo-hi", String(hiScore)); } catch {} }
    setMode("over");
    Sound.music(null);
    showBanner("GAME OVER", `FINAL SCORE ${fmt(S.score)}  ·  CLICK TO CONTINUE`, "enter");
    return;
  }
  serve();
  setMode("ready");
  showBanner(S.lives === 0 ? "LAST BALL" : "GET READY", `${S.lives} ${S.lives === 1 ? "LIFE" : "LIVES"} IN RESERVE`, "flash");
}

function roundClear() {
  const bonus = 1000 * (S.round + 1);
  addScore(bonus);
  setMode("clear");
  Sound.clear();
  showBanner("ROUND CLEAR", `BONUS +${fmt(bonus)}`, "flash");
  for (const b of S.balls) burst(b.x, b.y, P.accent, 30, 400);
  S.balls = []; S.bolts = [];
  for (const c of S.caps) c.actor.dispose();
  S.caps = [];
}

// ------------------------------------------------------------------ rendering (Canvas2D layer)
function drawField() {
  const { left, right, top } = FIELD;
  ctx.fillStyle = "rgba(9,8,17,0.74)";
  ctx.fillRect(left, top, right - left, H - top);
  const grad = ctx.createLinearGradient(0, top, 0, H);
  grad.addColorStop(0, P.accent); grad.addColorStop(1, P.primaryStrong);
  ctx.save();
  ctx.shadowColor = P.accent; ctx.shadowBlur = 18;
  ctx.fillStyle = grad;
  ctx.fillRect(left - 10, top - 10, 8, H - top + 10);
  ctx.fillRect(right + 2, top - 10, 8, H - top + 10);
  ctx.fillRect(left - 10, top - 10, right - left + 20, 8);
  ctx.restore();
  // subtle scanlines — a nod to the CRT
  ctx.fillStyle = "rgba(255,255,255,0.018)";
  for (let y = top; y < H; y += 4) ctx.fillRect(left, y, right - left, 1);
}

function drawBricks() {
  const t = S.time;
  for (const b of S.bricks) {
    if (!b.alive) continue;
    const spr = spriteFor(b);
    ctx.drawImage(spr, b.x - 4, b.y - 4, BW + 8, BH + 8);
    if (b.type === "x") {
      ctx.save(); ctx.globalCompositeOperation = "lighter"; ctx.globalAlpha = 0.25 + 0.2 * Math.sin(t * 6 + b.c);
      ctx.fillStyle = WARM.accent[1]; rrect(ctx, b.x + 2, b.y + 2, BW - 4, BH - 4, 5); ctx.fill(); ctx.restore();
    } else if (b.type === "s" || b.type === "g") {
      // periodic light sweep across metal
      const phase = ((t * 0.5 + b.c * 0.06 + b.r * 0.04) % 2.4) / 2.4;
      if (phase < 0.35) {
        const sx = b.x + (phase / 0.35) * (BW + 20) - 10;
        ctx.save(); rrect(ctx, b.x + 2, b.y + 2, BW - 4, BH - 4, 5); ctx.clip();
        ctx.globalAlpha = 0.55; ctx.fillStyle = "#fff";
        ctx.beginPath(); ctx.moveTo(sx, b.y); ctx.lineTo(sx + 8, b.y); ctx.lineTo(sx - 2, b.y + BH); ctx.lineTo(sx - 10, b.y + BH); ctx.fill(); ctx.restore();
      }
    }
    if (b.hit > 0) { ctx.save(); ctx.globalAlpha = b.hit * 0.8; ctx.fillStyle = "#fff"; rrect(ctx, b.x + 2, b.y + 2, BW - 4, BH - 4, 5); ctx.fill(); ctx.restore(); }
  }
}

function drawBalls() {
  const mega = S.fx.mega > 0;
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  for (const b of S.balls) {
    b.trail.forEach((p, i) => {
      const k = (i + 1) / b.trail.length;
      ctx.globalAlpha = k * (mega ? 0.55 : 0.3);
      ctx.fillStyle = mega ? (i % 2 ? WARM.primary[0] : WARM.primary[1]) : P.accent;
      ctx.beginPath(); ctx.arc(p.x, p.y, BALL_R * (mega ? 1.3 : 0.9) * k, 0, Math.PI * 2); ctx.fill();
    });
    ctx.globalAlpha = 0.5;
    const glow = ctx.createRadialGradient(b.x, b.y, 0, b.x, b.y, BALL_R * 3.2);
    glow.addColorStop(0, mega ? WARM.primary[0] : P.accent); glow.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = glow; ctx.beginPath(); ctx.arc(b.x, b.y, BALL_R * 3.2, 0, Math.PI * 2); ctx.fill();
  }
  ctx.restore();
  for (const b of S.balls) {
    const g = ctx.createRadialGradient(b.x - 3, b.y - 3, 1, b.x, b.y, BALL_R);
    g.addColorStop(0, "#fff"); g.addColorStop(0.5, mega ? "#ffd9a0" : "#bfeeff"); g.addColorStop(1, mega ? WARM.primary[1] : P.accent);
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(b.x, b.y, BALL_R, 0, Math.PI * 2); ctx.fill();
  }
}

function drawParticles() {
  ctx.save();
  for (const p of S.parts) {
    const k = p.life / p.max;
    if (p.ring) {
      ctx.globalCompositeOperation = "lighter";
      ctx.globalAlpha = k; ctx.strokeStyle = WARM.primary[0]; ctx.lineWidth = 6 * k;
      ctx.beginPath(); ctx.arc(p.x, p.y, (1 - k) * 110 + 10, 0, Math.PI * 2); ctx.stroke();
      continue;
    }
    ctx.globalCompositeOperation = "source-over";
    ctx.globalAlpha = Math.min(1, k * 1.5); ctx.fillStyle = p.color;
    ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(p.rot); ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size * 0.6); ctx.restore();
  }
  ctx.restore();
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  for (const l of S.bolts) {
    const g = ctx.createLinearGradient(0, l.y, 0, l.y + 26);
    g.addColorStop(0, "#fff"); g.addColorStop(0.3, WARM.primary[0]); g.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = g; ctx.fillRect(l.x - 2, l.y, 4, 26);
  }
  ctx.restore();
  ctx.textAlign = "center"; ctx.font = '18px "Audiowide"';
  for (const p of S.popups) {
    ctx.globalAlpha = 1 - p.t / 1.1; ctx.fillStyle = p.color;
    ctx.fillText(p.text, p.x, p.y - p.t * 40);
  }
  ctx.globalAlpha = 1;
}

function panel(x, y, w, h) {
  ctx.save();
  ctx.fillStyle = "rgba(20,18,28,0.72)"; rrect(ctx, x, y, w, h, 16); ctx.fill();
  const g = ctx.createLinearGradient(x, y, x + w, y + h);
  g.addColorStop(0, P.primarySoft); g.addColorStop(1, P.accentSoft);
  ctx.strokeStyle = g; ctx.lineWidth = 1.5; rrect(ctx, x + 0.75, y + 0.75, w - 1.5, h - 1.5, 16); ctx.stroke();
  ctx.restore();
}
function label(t, x, y) { ctx.fillStyle = P.textMuted; ctx.font = '600 12px "InterMB"'; ctx.letterSpacing = "3px"; ctx.fillText(t, x, y); ctx.letterSpacing = "0px"; }

function drawHud() {
  ctx.textAlign = "left"; ctx.textBaseline = "alphabetic";
  panel(28, 64, 216, 460);
  label("SCORE", 50, 104);
  ctx.fillStyle = P.text; ctx.font = '30px "Audiowide"'; ctx.fillText(fmt(S.score), 50, 142);
  label("HI-SCORE", 50, 190);
  ctx.fillStyle = P.primary; ctx.font = '22px "Audiowide"'; ctx.fillText(fmt(Math.max(hiScore, S.score)), 50, 222);
  label("ROUND", 50, 270);
  ctx.fillStyle = P.accent; ctx.font = '30px "Audiowide"'; ctx.fillText(String(S.round + 1).padStart(2, "0"), 50, 306);
  ctx.fillStyle = P.textMuted; ctx.font = '12px "InterMB"'; ctx.fillText(LEVELS[S.round % LEVELS.length].name, 50, 326);
  label("LIVES", 50, 374);
  for (let i = 0; i < Math.min(S.lives, 8); i++) {
    const x = 50 + (i % 4) * 44, y = 390 + Math.floor(i / 4) * 22;
    const g = ctx.createLinearGradient(0, y, 0, y + 10); g.addColorStop(0, tokens.gradients.primary[0]); g.addColorStop(1, tokens.gradients.primary[1]);
    ctx.fillStyle = g; rrect(ctx, x + 5, y + 1, 26, 8, 3); ctx.fill();
    ctx.fillStyle = P.accent; rrect(ctx, x, y, 8, 10, 3); ctx.fill(); rrect(ctx, x + 28, y, 8, 10, 3); ctx.fill();
  }
  label("ACTIVE", 50, 460);
  const active = [["LASER", S.fx.laser, 12], ["CATCH", S.fx.catch, 15], ["MEGA", S.fx.mega, 10], ["SLOW", S.fx.slow, 12], ["FAST", S.fx.fast, 10]].filter((a) => a[1] > 0);
  if (!active.length) { ctx.fillStyle = P.outline; ctx.font = '12px "InterMB"'; ctx.fillText("—", 50, 484); }
  active.slice(0, 2).forEach(([n, t, max], i) => {
    const y = 474 + i * 22;
    ctx.fillStyle = P.text; ctx.font = '11px "InterMB"'; ctx.fillText(n, 50, y + 9);
    ctx.fillStyle = P.outline; rrect(ctx, 102, y + 2, 118, 6, 3); ctx.fill();
    ctx.fillStyle = n === "FAST" ? WARM.accent[1] : P.accent; rrect(ctx, 102, y + 2, 118 * (t / max), 6, 3); ctx.fill();
  });

  panel(956, 64, 216, 460);
  label("CAPSULES", 978, 104);
  legend.forEach(({ k }, i) => {
    ctx.fillStyle = KINDS[k].good ? P.text : WARM.accent[0]; ctx.font = '600 13px "InterMB"';
    ctx.fillText(KINDS[k].name, 1054, 136 + i * 42);
  });
  ctx.fillStyle = P.textMuted; ctx.font = '11px "InterMB"'; ctx.textAlign = "center";
  ctx.fillText(Sound.muted ? "SOUND OFF · M" : "P PAUSE · M MUTE", 1064, 508);
  ctx.textAlign = "left";
}

function render() {
  const s = scale;
  const sx = S.shake ? rand(-S.shake, S.shake) * 0.5 : 0, sy = S.shake ? rand(-S.shake, S.shake) * 0.5 : 0;
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, gameCanvas.width, gameCanvas.height);
  ctx.setTransform(s, 0, 0, s, sx * s, sy * s);

  if (S.mode === "title") {
    ctx.fillStyle = "rgba(9,8,17,0.35)"; ctx.fillRect(-20, -20, W + 40, H + 40);
    if (hiScore) { ctx.textAlign = "center"; ctx.fillStyle = P.primary; ctx.font = '16px "Audiowide"'; ctx.fillText(`HI-SCORE  ${fmt(hiScore)}`, W / 2, 760); }
    if (!Sound.ready) { ctx.textAlign = "right"; ctx.fillStyle = P.textMuted; ctx.globalAlpha = 0.6 + 0.4 * Math.sin(S.time * 3); ctx.font = '13px "InterMB"'; ctx.fillText("♪  PRESS M FOR MUSIC", W - 32, 40); ctx.globalAlpha = 1; }
  } else {
    drawField();
    drawHud();
    drawBricks();
    drawBalls();
    drawParticles();
  }
  if (S.flash > 0) { ctx.fillStyle = `rgba(255,220,180,${S.flash * 0.35})`; ctx.fillRect(-20, -20, W + 40, H + 40); }

  // Rive layers
  bgRenderer.clear();
  backdrop.draw(bgRenderer, 0, 0);
  fxRenderer.clear();
  if (S.mode === "title" && title) title.draw(fxRenderer, 0, 0);
  else {
    legend.forEach(({ actor }, i) => actor.draw(fxRenderer, 972, 110 + i * 42, 0.9));
    for (const c of S.caps) c.actor.draw(fxRenderer, c.x - 40 + sx, c.y - 20 + sy);
    if (S.mode !== "over") paddleActor.draw(fxRenderer, S.paddle.x - PADDLE_CX + sx, PADDLE_Y - PADDLE_CY + sy);
  }
  banner.draw(fxRenderer, 0, 0);
}

// ------------------------------------------------------------------ main loop
resize();
toTitle();
let last = performance.now();
let lastError = null;
function frame(now) {
  // schedule first so a thrown error can never freeze the game on the backdrop
  requestAnimationFrame(frame);
  const dt = Math.min(0.033, Math.max(0, (now - last) / 1000));
  last = now;
  try {
    if (!S.paused) {
      update(dt);
      paddleActor.advance(dt);
      for (const l of legend) l.actor.advance(dt);
      if (title) title.advance(dt);
    }
    backdrop.advance(dt);
    banner.advance(dt);
    render();
  } catch (err) {
    if (String(err) !== lastError) { lastError = String(err); console.error("[megaball] frame error:", err); showError(err); }
  }
  // flush Rive's queued draws (we drive the loop with the standard rAF)
  rive.resolveAnimationFrame();
}
function showError(err) {
  let el = document.getElementById("error");
  if (!el) { el = document.createElement("pre"); el.id = "error"; stage.appendChild(el); }
  el.textContent = `Something went wrong — please report this:\n${err && err.stack ? err.stack.split("\n").slice(0, 4).join("\n") : err}`;
}
window.addEventListener("error", (e) => showError(e.error || e.message));
window.addEventListener("unhandledrejection", (e) => showError(e.reason));
requestAnimationFrame(frame);

// debugging hook for automated checks
window.__megaball = { S, LEVELS, newGame, loadRound, startRound, applyCapsule, dropCapsule };
